def build_playbook(industry_key: str) -> dict:
    """Return a deep-copied, industry-specific handbook package."""
    detail = deepcopy(INDUSTRY.get(industry_key, INDUSTRY["general-enterprise"]))
    detail["organization_models"] = deepcopy(ORG_MODELS)
    detail["raci"] = deepcopy(RACI)
    detail["work_plan"] = deepcopy(WORK_PLAN)
    detail["shared_policies"] = deepcopy(COMMON_POLICIES)
    detail["practice_note"] = "工作日和抽样数量是可编辑的项目计划建议，不是监管期限或统计性行业基准。管理层应按复杂度、风险、资源和适用规则调整。"
    detail["public_cases"] = deepcopy(detail.get("public_cases", []))
    detail["sources"] = deepcopy(detail.get("sources", []))
    return detail
